INSERT INTO public.books (id, title, author, cover_url, price, old_price, rating, review_count, badge, genre, pages, publisher, publish_year, description, is_premium, is_active) VALUES
('1', 'Atomic Habits', 'James Clear', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=500', 79000, 99000, 4.9, 1284, 'Best Seller', 'Self Improvement', 320, 'Gramedia', 2020, 'Atomic Habits menawarkan kerangka kerja yang telah terbukti untuk memperbaiki setiap hari. James Clear, salah satu penulis terkemuka di dunia dalam hal pembentukan kebiasaan, mengungkapkan strategi-strategi praktis yang akan mengajarkan Anda cara membentuk kebiasaan baik, menghilangkan yang buruk, dan menguasai perilaku-perilaku kecil yang menghasilkan hasil luar biasa.', false, true),
('2', 'Filosofi Teras', 'Henry Manampiring', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=500', 85000, NULL, 4.8, 987, 'Populer', 'Self Improvement', 288, 'Kompas', 2019, 'Filosofi Teras membahas filsafat Stoa dari sudut pandang yang relevan dengan kehidupan modern Indonesia. Buku ini mengajak pembaca untuk menemukan ketenangan dan kebahagiaan sejati di tengah dunia yang penuh tekanan.', false, true),
('3', 'Deep Work', 'Cal Newport', 'https://images.unsplash.com/photo-1495446815901-a7297e633e8d?w=500', 72000, NULL, 4.9, 756, NULL, 'Bisnis', 304, 'Grand Central Publishing', 2016, 'Deep Work adalah kemampuan untuk fokus tanpa gangguan pada tugas yang menuntut kognitif. Buku ini menunjukkan mengapa kemampuan ini semakin langka dan semakin berharga di dunia saat ini.', false, true),
('4', 'Psychology of Money', 'Morgan Housel', 'https://images.unsplash.com/photo-1516979187457-637abb4f9353?w=500', 91000, NULL, 5.0, 1102, 'Editor''s Pick', 'Bisnis', 268, 'Harriman House', 2020, 'Buku ini mengungkapkan cara orang berpikir tentang uang dan cara mengubah pola pikir itu untuk membuat keputusan keuangan yang lebih baik.', false, true),
('5', 'Ikigai', 'Hector Garcia', 'https://images.unsplash.com/photo-1541963463532-d68292c34b19?w=500', 82000, NULL, 4.8, 843, NULL, 'Self Improvement', 208, 'Penguin Books', 2017, 'Ikigai adalah kata Jepang yang berarti alasan untuk hidup. Buku ini menjelajahi rahasia kebahagiaan dan umur panjang orang-orang di Okinawa, Jepang.', false, true),
('6', 'Bumi', 'Tere Liye', 'https://images.unsplash.com/photo-1481627834876-b7833e8f5570?w=500', 69000, NULL, 4.7, 654, NULL, 'Fantasi', 440, 'Gramedia', 2014, 'Raib, gadis 15 tahun yang bisa menghilang, suatu hari menemukan pintu menuju dunia lain dengan peradaban yang jauh lebih maju.', false, true),
('7', 'Laut Bercerita', 'Leila S. Chudori', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=500', 91000, NULL, 5.0, 921, 'Editor''s Pick', 'Novel', 384, 'KPG', 2017, 'Novel tentang mahasiswa aktivis yang hilang di era Orde Baru, diceritakan dari dua sudut pandang: Biru Laut yang hilang, dan adiknya Asmara Jati yang terus mencari.', false, true),
('8', 'Sapiens', 'Yuval Noah Harari', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=500', 105000, NULL, 5.0, 1589, 'Best Seller', 'Sejarah', 512, 'Harper', 2011, 'Dari manusia purba hingga era teknologi modern, Sapiens mengajak kita menelusuri perjalanan luar biasa umat manusia.', true, true),
('9', 'The Mountain Is You', 'Brianna Wiest', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=500', 95000, NULL, 5.0, 778, 'New', 'Self Improvement', 248, 'Thought Catalog Books', 2020, 'Buku transformatif tentang cara mengatasi hambatan diri sendiri.', false, true),
('10', 'Start With Why', 'Simon Sinek', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=500', 89000, NULL, 4.8, 1034, NULL, 'Bisnis', 256, 'Portfolio', 2009, 'Simon Sinek mengungkap pola pikir yang membedakan pemimpin dan organisasi yang menginspirasi dari yang lainnya.', false, true),
('11', 'Rich Dad Poor Dad', 'Robert T. Kiyosaki', 'https://images.unsplash.com/photo-1543286386-2e659306cd6c?w=500', 74000, NULL, 4.8, 2001, 'Best Seller', 'Bisnis', 336, 'Warner Books', 1997, 'Robert Kiyosaki berbagi pelajaran keuangan yang ia pelajari dari dua ayah.', false, true),
('12', 'Thinking, Fast and Slow', 'Daniel Kahneman', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=500', 99000, NULL, 4.9, 1356, NULL, 'Teknologi', 499, 'Farrar, Straus and Giroux', 2011, 'Daniel Kahneman mengungkapkan dua sistem berpikir manusia dan bagaimana keduanya mempengaruhi setiap keputusan kita.', true, true)
