-- Chapters untuk semua buku
INSERT INTO public.chapters (book_id, title, content, order_num, is_free) VALUES
-- Atomic Habits
('1', 'Bab 1 — Kekuatan Kebiasaan Kecil', 'Kebiasaan kecil yang dilakukan secara konsisten akan menghasilkan perubahan besar. James Clear menjelaskan bagaimana 1% perbaikan setiap hari dapat menghasilkan hasil yang luar biasa dalam jangka panjang. Bayangkan jika Anda bisa menjadi 1% lebih baik setiap hari selama setahun - Anda akan 37 kali lebih baik pada akhir tahun itu. Sebaliknya, jika Anda 1% lebih buruk setiap hari selama setahun, Anda akan menurun hampir ke nol.', 1, true),
('1', 'Bab 2 — Identitas & Kebiasaan', 'Perubahan sejati dimulai dari identitas, bukan dari hasil yang diinginkan. Kebanyakan orang memulai dengan memikirkan hasil (saya ingin kurus), kemudian proses (diet dan olahraga ini), dan identitas (saya yang baru). Clear menyarankan urutan terbalik: mulailah dengan identitas siapa yang ingin Anda jadikan.', 2, false),
('1', 'Bab 3 — Cara Membangun Kebiasaan Baru', 'Empat langkah untuk membangun kebiasaan: Isyarat (Cue), Keinginan (Craving), Respons (Response), dan Hadiah (Reward). Setiap kebiasaan dimulai dengan isyarat yang memicu otak untuk memulai perilaku, karena isyarat itu memprediksi hadiah. Keinginan adalah kekuatan motivasi di balik setiap kebiasaan.', 3, false),
('1', 'Bab 4 — Hukum Pertama: Buat Tampak Jelas', 'Hukum pertama perubahan perilaku adalah membuat isyarat kebiasaan baik Anda tampak jelas dan terlihat. Jika Anda ingin membangun kebiasaan, Anda perlu membuatnya lebih mudah dilakukan. Jika Anda ingin menghentikan kebiasaan buruk, Anda perlu membuatnya lebih tidak terlihat.', 4, false),
('1', 'Bab 5 — Hukum Kedua: Buat Menarik', 'Semakin menarik sebuah kesempatan, semakin besar kemungkinan membentuk suatu kebiasaan. Anda dapat membuat kebiasaan baik lebih menarik dengan menggunakan strategi penumpukan kebiasaan, di mana Anda menggabungkan tindakan yang perlu Anda lakukan dengan tindakan yang ingin Anda lakukan.', 5, false),
-- Filosofi Teras
('2', 'Bab 1 — Apa Itu Stoisisme?', 'Stoisisme adalah mazhab filsafat Yunani yang didirikan sekitar tahun 300 SM oleh Zeno dari Citium. Stoisisme mengajarkan bahwa kebajikan, yang didasarkan pada pengetahuan, adalah satu-satunya kebaikan sejati. Buku ini menjelaskan bagaimana prinsip-prinsip Stoa bisa diterapkan dalam kehidupan modern Indonesia.', 1, true),
('2', 'Bab 2 — Dikotomi Kendali', 'Prinsip inti Stoisisme adalah membedakan apa yang ada dalam kendali kita dan apa yang tidak. Pikiran, perasaan, dan tindakan kita berada dalam kendali kita. Kejadian eksternal tidak. Dengan fokus hanya pada apa yang bisa kita kendalikan, kita bisa menemukan kedamaian sejati.', 2, false),
('2', 'Bab 3 — Emosi Negatif', 'Stoisisme mengajarkan bahwa emosi negatif seperti kecemasan, kemarahan, dan kesedihan bukanlah akibat dari peristiwa yang menimpa kita, melainkan akibat dari cara kita menilai peristiwa tersebut. Dengan mengubah penilaian kita, kita bisa mengubah emosi kita.', 3, false),
('2', 'Bab 4 — Membangun Resiliensi', 'Resiliensi adalah kemampuan untuk bangkit dari kegagalan dan tantangan. Stoisisme menawarkan praktik konkret untuk membangun resiliensi: visualisasi negatif, memfokuskan perhatian pada momen sekarang, dan memandang setiap rintangan sebagai peluang untuk berkembang.', 4, false),
-- Deep Work
('3', 'Bab 1 — Deep Work Bernilai', 'Deep Work, atau kerja mendalam, adalah kemampuan untuk fokus tanpa gangguan pada tugas yang menuntut kognitif. Kemampuan ini menghasilkan nilai luar biasa di ekonomi saat ini, karena menciptakan produk yang sulit ditiru dan mendorong Anda ke batas kemampuan kognitif Anda.', 1, true),
('3', 'Bab 2 — Deep Work Langka', 'Ironisnya, meskipun Deep Work semakin berharga, Deep Work semakin jarang dilakukan. Budaya bisnis yang mendominasi - email, media sosial, pertemuan terus-menerus - secara aktif menghancurkan kemampuan untuk fokus mendalam.', 2, false),
('3', 'Bab 3 — Deep Work Bermakna', 'Selain bernilai secara ekonomi, Deep Work juga bermakna secara psikologis. Penelitian menunjukkan bahwa kondisi flow - keadaan keterlibatan penuh dan fokus mendalam - adalah salah satu sumber utama kebahagiaan yang dilaporkan oleh manusia.', 3, false),
('3', 'Bab 4 — Aturan 1: Bekerja Dalam-Dalam', 'Untuk melakukan Deep Work secara konsisten, Anda memerlukan ritual dan strategi. Newport membahas berbagai filosofi Deep Work: monastik (menghilangkan semua gangguan), bimodal (bergantian antara mode mendalam dan dangkal), ritmis (jadwal harian yang konsisten), dan jurnalistik.', 4, false),
-- Psychology of Money
('4', 'Bab 1 — Tidak Ada yang Gila', 'Orang membuat keputusan keuangan yang aneh bukan karena mereka bodoh, tetapi karena mereka memiliki pengalaman berbeda yang membentuk perspektif berbeda tentang uang. Seorang yang tumbuh dalam kemiskinan dan seseorang yang lahir dalam kemewahan akan memiliki pandangan sangat berbeda tentang risiko dan nilai.', 1, true),
('4', 'Bab 2 — Keberuntungan & Risiko', 'Keberuntungan dan risiko adalah saudara kandung. Keduanya adalah kenyataan bahwa setiap hasil dalam kehidupan adalah dipandu oleh kekuatan selain usaha individu. Housel mengingatkan kita untuk tidak terlalu mengagungkan kesuksesan orang lain atau terlalu menyalahkan kegagalan orang lain, karena nasib memainkan peran yang lebih besar dari yang kita akui.', 2, false),
('4', 'Bab 3 — Tidak Pernah Cukup', 'Kemampuan untuk mengatakan "cukup" adalah salah satu keterampilan keuangan yang paling berharga, tetapi jarang dibicarakan. Banyak orang kaya yang menghancurkan karir dan reputasi mereka karena ketidakmampuan mengatakan cukup.', 3, false),
('4', 'Bab 4 — Membungakan Waktu', 'Warren Buffett memiliki kekayaan sekitar $84 miliar. Darinya, $81 miliar diperoleh setelah ulang tahun ke-65. Rahasia sebenarnya dari kekayaan Buffett bukan hanya tentang investasi yang baik, tetapi tentang investasi yang baik selama 70 tahun. Ini adalah kekuatan bunga berbunga.', 4, false),
-- Ikigai
('5', 'Bab 1 — Ikigai, Seni Tetap Muda', 'Orang-orang di Okinawa, Jepang, memiliki usia harapan hidup tertinggi di dunia. Salah satu rahasianya adalah ikigai - alasan untuk bangun di pagi hari. Ikigai adalah persimpangan antara apa yang Anda cintai, apa yang Anda kuasai, apa yang dunia butuhkan, dan apa yang bisa menghasilkan uang bagi Anda.', 1, true),
('5', 'Bab 2 — Anti-Penuaan', 'Penelitian menunjukkan bahwa tetap aktif secara mental dan fisik, memiliki tujuan hidup, dan mempertahankan koneksi sosial adalah kunci untuk menua dengan anggun. Orang-orang di Okinawa jarang pensiun sepenuhnya; mereka terus bergerak dan berkontribusi sesuai kemampuan.', 2, false),
('5', 'Bab 3 — Flow', 'Flow adalah keadaan di mana Anda begitu tenggelam dalam suatu aktivitas sehingga Anda kehilangan jejak waktu. Ini adalah kondisi ideal antara bosan dan cemas - ketika tantangan sesuai dengan kemampuan Anda. Menemukan aktivitas yang mendatangkan flow adalah bagian penting dari menemukan ikigai.', 3, false),
-- Bumi
('6', 'Bab 1 — Raib yang Bisa Menghilang', 'Raib adalah gadis SMP yang tampak biasa, kecuali satu hal: dia bisa menghilang. Kemampuan itu dimilikinya sejak kecil, tetapi dia tidak pernah memahami asal-usulnya. Suatu hari, petualangan yang tidak terduga mengubah hidupnya selamanya.', 1, true),
('6', 'Bab 2 — Pintu Rahasia', 'Di balik lemari tua di kamarnya, Raib menemukan pintu yang membawanya ke dunia lain. Dunia yang indah namun berbahaya, dengan teknologi yang jauh melampaui Bumi, tetapi juga dengan ancaman yang mengintai dari bayangan.', 2, false),
('6', 'Bab 3 — Dunia Bawah Tanah', 'Bersama dua sahabat setianya, Raib menjelajahi dunia bawah tanah yang menakjubkan. Mereka menemukan bahwa kemampuan Raib bukan kebetulan - ada warisan dan takdir yang menunggunya.', 3, false),
-- Laut Bercerita
('7', 'Bab 1 — Biru Laut', 'Biru Laut adalah mahasiswa aktivis tahun 1990-an yang berjuang melawan penindasan. Kisahnya dimulai dari momen-momen sebelum penghilangannya, memperlihatkan keberanian, cinta, dan keyakinan seorang pemuda yang percaya perubahan adalah mungkin.', 1, true),
('7', 'Bab 2 — Asmara Jati', 'Asmara Jati, adik Biru Laut, hidup dalam duka dan ketidakpastian setelah kakaknya menghilang. Bertahun-tahun kemudian, dia masih mencari kebenaran tentang apa yang terjadi pada saudaranya.', 2, false),
('7', 'Bab 3 — 1998', 'Reformasi 1998 menjadi latar belakang kisah ini - masa di mana banyak mahasiswa hilang tanpa jejak. Leila S. Chudori dengan indah menggambarkan bagaimana sejarah meninggalkan luka yang tak pernah sembuh pada mereka yang ditinggalkan.', 3, false),
-- Sapiens
('8', 'Bab 1 — Binatang yang Tidak Penting', 'Sekitar 13,5 miliar tahun yang lalu, materi, energi, waktu, dan ruang muncul dalam apa yang dikenal sebagai Big Bang. Tiga ratus ribu tahun kemudian, materi dan energi mulai bergumpal menjadi struktur kompleks yang disebut atom. Dari sana, evolusi berlanjut hingga munculnya Homo sapiens - binatang yang paling tidak penting, hingga tiba-tiba menjadi penguasa planet.', 1, true),
('8', 'Bab 2 — Pohon Pengetahuan', 'Revolusi Kognitif terjadi sekitar 70.000 tahun yang lalu dan merupakan titik balik terbesar dalam sejarah manusia. Tiba-tiba, Homo sapiens mampu berpikir dan berkomunikasi dengan cara yang sama sekali baru, memungkinkan mereka untuk membangun jaringan sosial yang lebih kompleks dari spesies lain.', 2, false),
-- The Mountain Is You
('9', 'Bab 1 — Mengapa Kita Menyabotase Diri', 'Sabotase diri adalah cara kita melindungi diri dari sesuatu yang kita percaya tidak bisa kita tangani. Perilaku yang tampak merusak seringkali adalah upaya untuk menghindari emosi yang lebih menyakitkan - rasa takut akan kegagalan, penolakan, atau pengulangan pola lama.', 1, true),
('9', 'Bab 2 — Kebiasaan Merusak', 'Kebiasaan merusak adalah respons terhadap emosi yang tidak terproses. Sebelum Anda bisa mengubah perilaku, Anda harus memahami apa yang mendasarinya. Setiap kebiasaan buruk adalah petunjuk tentang kebutuhan yang belum terpenuhi.', 2, false),
('9', 'Bab 3 — Membangun Diri Baru', 'Membangun diri baru dimulai dengan pertanyaan sederhana: siapa yang ingin saya jadikan? Bukan apa yang ingin saya capai, tetapi siapa yang ingin saya jadikan. Identitas menentukan tindakan, bukan sebaliknya.', 3, false),
-- Start With Why
('10', 'Bab 1 — Asumsikan Anda Tahu', 'Manipulasi versus inspirasi: ada dua cara untuk mempengaruhi perilaku manusia - manipulasi dan inspirasi. Pemimpin dan organisasi yang paling sukses bukan yang terbaik dalam apa yang mereka lakukan, tetapi yang paling jelas tentang mengapa mereka melakukannya.', 1, true),
('10', 'Bab 2 — Golden Circle', 'Golden Circle adalah tiga lingkaran konsentris: Mengapa (inti), Bagaimana (tengah), dan Apa (luar). Semua orang tahu APA yang mereka lakukan. Beberapa tahu BAGAIMANA. Sangat sedikit yang tahu MENGAPA. Pemimpin yang menginspirasi berpikir, bertindak, dan berkomunikasi dari dalam ke luar.', 2, false),
('10', 'Bab 3 — Pemimpin yang Menginspirasi', 'Apple, Martin Luther King, dan Wright Brothers memiliki satu kesamaan: mereka dimulai dengan MENGAPA. Mereka tidak menjual apa yang mereka buat; mereka menjual mengapa mereka membuatnya. Dan itulah yang menciptakan pengikut yang loyal, bukan sekadar pelanggan.', 3, false),
-- Rich Dad Poor Dad
('11', 'Bab 1 — Rich Dad, Poor Dad', 'Robert Kiyosaki memiliki dua ayah - ayah kandungnya yang berpendidikan tinggi namun selalu berjuang secara finansial, dan ayah teman sekolahnya yang putus sekolah namun menjadi salah satu orang terkaya di Hawaii. Dua pria ini memberinya sudut pandang yang sangat berbeda tentang uang.', 1, true),
('11', 'Bab 2 — Orang Kaya Tidak Bekerja untuk Uang', 'Orang miskin dan kelas menengah bekerja untuk uang. Orang kaya membuat uang bekerja untuk mereka. Perbedaan utama bukan pada pendapatan, tetapi pada bagaimana mereka berpikir tentang dan menggunakan uang.', 2, false),
('11', 'Bab 3 — Melek Finansial', 'Kecerdasan finansial adalah fondasi dari kekayaan sejati. Ini melibatkan pemahaman akuntansi dasar, investasi, hukum pajak, dan dinamika pasar. Sekolah tidak mengajarkan ini, itulah mengapa banyak orang berpenghasilan tinggi tetapi tetap miskin.', 3, false),
-- Thinking, Fast and Slow
('12', 'Bab 1 — Karakter Cerita', 'Kahneman memperkenalkan dua sistem berpikir: Sistem 1 yang cepat, intuitif, dan emosional; dan Sistem 2 yang lambat, deliberatif, dan logis. Sebagian besar pemikiran kita dikendalikan oleh Sistem 1, yang efisien tetapi rentan terhadap bias.', 1, true),
('12', 'Bab 2 — Perhatian dan Usaha', 'Sistem 2 membutuhkan perhatian dan usaha. Ketika kita fokus pada tugas yang sulit, kita menggunakan sumber daya kognitif yang terbatas. Inilah mengapa pengambilan keputusan yang sulit sangat melelahkan.', 2, false),
('12', 'Bab 3 — Mesin Lompatan Kesimpulan', 'Sistem 1 mahir membuat narasi kohesif dari informasi yang terbatas. Ini berguna untuk keputusan sehari-hari, tetapi berbahaya untuk keputusan penting. Kita sering terlalu percaya diri pada kesimpulan yang dibuat dari data yang tidak mencukupi.', 3, false)
ON CONFLICT DO NOTHING;
